content.content:
1	/**
2	 * Feature Reviewer Daemon (T4).
3	 *
4	 * Poll step that runs every FEATURE_REVIEW_INTERVAL cycles. For each
5	 * in_handoff feature it detects drift (new commits on the base branch since
6	 * the feature started) and routes to one of three outcomes:
7	 *
8	 *   1. No new commits → skip.
9	 *   2. New commits, no file overlap → auto-rebase feature branch onto base;
10	 *      on rebase conflict fall through to escalation.
11	 *   3. New commits, file overlap → optional Claude API semantic analysis
12	 *      (confidence ≥ threshold → treat as no-overlap/auto-rebase;
13	 *       confidence < threshold → feature-level escalation).
14	 *
15	 * Feature-level escalation:
16	 *   - Sets drift_detected: true + drift_reason in status.yaml on the feature branch.
17	 *   - POSTs to SLACK_WEBHOOK_URL if set; skips gracefully if absent.
18	 */
19	
20	import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
21	import { execSync, spawnSync } from "node:child_process";
22	import { join } from "node:path";
23	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
24	import { buildGitEnv } from "../git-env.js";
25	import { curlJson } from "../utils/curl-json.js";
26	import {
27	  featuresRoot,
28	  featureBranchName,
29	  statusYamlAbsPath,
30	  statusYamlRelPath,
31	} from "../paths.js";
32	
33	// ── Types ─────────────────────────────────────────────────────────────────────
34	
35	export interface RunFeatureReviewCycleOpts {
36	  workspaceRoot: string;
37	  baseBranch: string;
38	  mgmtRepoOwner: string;
39	  mgmtRepoName: string;
40	  githubToken: string;
41	  reviewerGithubToken?: string;
42	  gitAuthorEmail: string;
43	  gitAuthorName?: string;
44	  sshKeyPath?: string;
45	  anthropicApiKey?: string;
46	  slackWebhookUrl?: string;
47	  /** Confidence threshold for semantic analysis. Default: 0.80. */
48	  semanticConfidenceThreshold?: number;
49	  emit: (event: Record<string, unknown>) => void;
50	}
51	
52	interface StatusYaml {
53	  feature_status?: string;
54	  feature_branch?: string;
55	  feature_branch_base_sha?: string | null;
56	  handoff_pr_url?: string | null;
57	  impl_feature_prs?: ImplFeaturePr[];
58	  drift_detected?: boolean;
59	  drift_reason?: string | null;
60	  [key: string]: unknown;
61	}
62	
63	interface ImplFeaturePr {
64	  repo: string;
65	  url: string;
66	  status: "open" | "merged";
67	}
68	
69	interface GitHubCompareResult {
70	  ahead_by: number;
71	  files?: GitHubFile[];
72	  [key: string]: unknown;
73	}
74	
75	interface GitHubFile {
76	  filename: string;
77	  status: string;
78	  patch?: string;
79	  [key: string]: unknown;
80	}
81	
82	export interface SemanticAnalysisResult {
83	  confidence: number;
84	  hasConflict: boolean;
85	  reasoning: string;
86	}
87	
88	// ── Helpers ───────────────────────────────────────────────────────────────────
89	
90	function listFeatureIds(workspaceRoot: string): string[] {
91	  const docsPath = featuresRoot(workspaceRoot);
92	  if (!existsSync(docsPath)) return [];
93	  try {
94	    return readdirSync(docsPath, { withFileTypes: true })
95	      .filter((e) => e.isDirectory())
96	      .map((e) => e.name);
97	  } catch {
98	    return [];
99	  }
100	}
101	
102	function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
103	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
104	  if (!existsSync(statusPath)) return {};
105	  try {
106	    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
107	  } catch {
108	    return {};
109	  }
110	}
111	
112	/**
113	 * Classify whether new base commits overlap with files changed by the feature.
114	 * Exported for unit testing.
115	 */
116	export function classifyFileOverlap(
117	  newBaseFiles: string[],
118	  featureFiles: string[],
119	): { hasOverlap: boolean; overlappingFiles: string[] } {
120	  const featureFileSet = new Set(featureFiles);
121	  const overlappingFiles = newBaseFiles.filter((f) => featureFileSet.has(f));
122	  return { hasOverlap: overlappingFiles.length > 0, overlappingFiles };
123	}
124	
125	/**
126	 * Call Claude API to semantically classify whether overlapping file changes
127	 * are likely to conflict. Returns a confidence score and conflict verdict.
128	 * Exported for unit testing with a mocked fetch.
129	 */
130	export async function runSemanticAnalysis(
131	  overlappingFiles: string[],
132	  newBaseFileSummary: string,
133	  featureFileSummary: string,
134	  anthropicApiKey: string,
135	  technicalDesignSummary?: string,
136	): Promise<SemanticAnalysisResult> {
137	  const prompt = [
138	    "You are analyzing whether code changes from two separate sources conflict.",
139	    "",
140	    `Files changed in both new base commits and the in-progress feature: ${overlappingFiles.join(", ")}`,
141	    "",
142	    "New base commit changes (filename, status, and patch excerpt):",
143	    newBaseFileSummary.slice(0, 2000),
144	    "",
145	    "In-progress feature changes (summary):",
146	    featureFileSummary.slice(0, 2000),
147	    "",
148	    ...(technicalDesignSummary
149	      ? [
150	          "Feature technical design (excerpt):",
151	          technicalDesignSummary.slice(0, 2000),
152	          "",
153	        ]
154	      : []),
155	    "Do these changes conflict semantically? Respond ONLY with valid JSON:",
156	    '{"confidence": <0.0-1.0, where 1.0 = certain no conflict>, "has_conflict": <boolean>, "reasoning": "<one sentence>"}',
157	  ].join("\n");
158	
159	  const response = await fetch("https://api.anthropic.com/v1/messages", {
160	    method: "POST",
161	    headers: {
162	      "x-api-key": anthropicApiKey,
163	      "anthropic-version": "2023-06-01",
164	      "content-type": "application/json",
165	    },
166	    body: JSON.stringify({
167	      model: "claude-haiku-4-5-20251001",
168	      max_tokens: 256,
169	      messages: [{ role: "user", content: prompt }],
170	    }),
171	  });
172	
173	  if (!response.ok) {
174	    throw new Error(`Anthropic API error ${response.status}: ${await response.text()}`);
175	  }
176	
177	  const data = (await response.json()) as {
178	    content: Array<{ type: string; text: string }>;
179	  };
180	  const text = data.content.find((c) => c.type === "text")?.text ?? "";
181	
182	  const jsonMatch = /\{[\s\S]*?\}/.exec(text);
183	  if (!jsonMatch) {
184	    throw new Error(`Cannot parse semantic analysis JSON from: ${text}`);
185	  }
186	
187	  const parsed = JSON.parse(jsonMatch[0]) as {
188	    confidence: number;
189	    has_conflict: boolean;
190	    reasoning: string;
191	  };
192	
193	  return {
194	    confidence: parsed.confidence,
195	    hasConflict: parsed.has_conflict,
196	    reasoning: parsed.reasoning,
197	  };
198	}
199	
200	/**
201	 * Attempt to rebase the feature branch onto the base branch.
202	 * Returns success: true and pushes on clean rebase.
203	 * Returns success: false (with conflictDetails) if rebase conflicts or push fails.
204	 */
205	export function tryAutoRebase(
206	  opts: Pick<
207	    RunFeatureReviewCycleOpts,
208	    "workspaceRoot" | "baseBranch" | "gitAuthorEmail" | "gitAuthorName" | "sshKeyPath" | "emit"
209	  >,
210	  featureId: string,
211	): { success: boolean; conflictDetails?: string } {
212	  const {
213	    workspaceRoot,
214	    baseBranch,
215	    gitAuthorEmail,
216	    gitAuthorName = gitAuthorEmail,
217	    sshKeyPath,
218	    emit,
219	  } = opts;
220	  const featureBranch = featureBranchName(featureId);
221	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
222	
223	  try {
224	    execSync("git fetch origin", {
225	      cwd: workspaceRoot,
226	      env,
227	      encoding: "utf-8",
228	      stdio: "pipe",
229	      timeout: 60_000,
230	    });
231	    execSync(`git checkout -B "${featureBranch}" "origin/${featureBranch}"`, {
232	      cwd: workspaceRoot,
233	      env,
234	      encoding: "utf-8",
235	      stdio: "pipe",
236	      timeout: 30_000,
237	    });
238	  } catch (e) {
239	    return { success: false, conflictDetails: `checkout failed: ${String(e)}` };
240	  }
241	
242	  try {
243	    execSync(`git rebase "origin/${baseBranch}"`, {
244	      cwd: workspaceRoot,
245	      env,
246	      encoding: "utf-8",
247	      stdio: "pipe",
248	      timeout: 60_000,
249	    });
250	  } catch (rebaseErr) {
251	    try {
252	      execSync("git rebase --abort", {
253	        cwd: workspaceRoot,
254	        env,
255	        encoding: "utf-8",
256	        stdio: "pipe",
257	        timeout: 30_000,
258	      });
259	    } catch { /* ignore abort errors */ }
260	    return {
261	      success: false,
262	      conflictDetails:
263	        (rebaseErr as { stderr?: string }).stderr?.slice(0, 500) ?? String(rebaseErr),
264	    };
265	  }
266	
267	  const pushResult = spawnSync(
268	    "git",
269	    ["-C", workspaceRoot, "push", "origin", featureBranch, "--force-with-lease"],
270	    { env, encoding: "utf-8" },
271	  );
272	
273	  if (pushResult.status !== 0) {
274	    emit({
275	      type: "feature_review_push_failed",
276	      feature_id: featureId,
277	      details: pushResult.stderr,
278	    });
279	    return { success: false, conflictDetails: pushResult.stderr };
280	  }
281	
282	  return { success: true };
283	}
284	
285	/**
286	 * Write drift_detected + drift_reason to status.yaml, commit + push to the
287	 * feature branch, and post a Slack message if SLACK_WEBHOOK_URL is set.
288	 */
289	async function escalateFeatureDrift(
290	  opts: RunFeatureReviewCycleOpts,
291	  featureId: string,
292	  driftReason: string,
293	): Promise<void> {
294	  const {
295	    workspaceRoot,
296	    gitAuthorEmail,
297	    gitAuthorName = gitAuthorEmail,
298	    sshKeyPath,
299	    slackWebhookUrl,
300	    emit,
301	  } = opts;
302	
303	  const featureBranch = featureBranchName(featureId);
304	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
305	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
306	  const statusRel = statusYamlRelPath(featureId);
307	  let handoffPrUrl: string | null | undefined;
308	
309	  try {
310	    execSync("git fetch origin", {
311	      cwd: workspaceRoot,
312	      env,
313	      encoding: "utf-8",
314	      stdio: "pipe",
315	      timeout: 60_000,
316	    });
317	    execSync(`git checkout -B "${featureBranch}" "origin/${featureBranch}"`, {
318	      cwd: workspaceRoot,
319	      env,
320	      encoding: "utf-8",
321	      stdio: "pipe",
322	      timeout: 30_000,
323	    });
324	
325	    const freshStatus = readStatusYaml(workspaceRoot, featureId);
326	    handoffPrUrl = freshStatus.handoff_pr_url;
327	    freshStatus.drift_detected = true;
328	    freshStatus.drift_reason = driftReason;
329	    writeFileSync(statusPath, yamlStringify(freshStatus), "utf-8");
330	
331	    execSync(`git add "${statusRel}"`, {
332	      cwd: workspaceRoot,
333	      env,
334	      encoding: "utf-8",
335	      stdio: "pipe",
336	      timeout: 10_000,
337	    });
338	    try {
339	      execSync(
340	        `git commit -m "chore(${featureId}): drift_detected — base branch advanced"`,
341	        { cwd: workspaceRoot, env, encoding: "utf-8", stdio: "pipe", timeout: 30_000 },
342	      );
343	    } catch (e) {
344	      const stderr = (e as { stderr?: string }).stderr ?? String(e);
345	      if (!stderr.includes("nothing to commit")) throw e;
346	    }
347	
348	    const pushResult = spawnSync(
349	      "git",
350	      ["-C", workspaceRoot, "push", "origin", featureBranch],
351	      { env, encoding: "utf-8" },
352	    );
353	    if (pushResult.status !== 0) {
354	      emit({
355	        type: "drift_escalation_push_failed",
356	        feature_id: featureId,
357	        details: pushResult.stderr,
358	      });
359	    }
360	  } catch (e) {
361	    emit({ type: "drift_escalation_failed", feature_id: featureId, details: String(e) });
362	    return;
363	  }
364	
365	  emit({ type: "drift_escalated", feature_id: featureId, drift_reason: driftReason });
366	
367	  // Post a PR comment using the reviewer token so the escalation is visible on the PR.
368	  const prToken = opts.reviewerGithubToken ?? opts.githubToken;
369	  if (handoffPrUrl) {
370	    const prMatch = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)$/.exec(handoffPrUrl);
371	    if (prMatch) {
372	      const [, prOwner, prRepo, prNumber] = prMatch;
373	      try {
374	        curlJson([
375	          "-s", "-X", "POST",
376	          "-H", `Authorization: token ${prToken}`,
377	          "-H", "Accept: application/vnd.github+json",
378	          `https://api.github.com/repos/${prOwner}/${prRepo}/issues/${prNumber}/comments`,
379	          "-d", JSON.stringify({ body: `**[Drift Detected]** ${driftReason}` }),
380	        ]);
381	      } catch (e) {
382	        emit({ type: "drift_pr_comment_failed", feature_id: featureId, details: String(e) });
383	      }
384	    }
385	  }
386	
387	  if (slackWebhookUrl) {
388	    const slackBody = [
389	      `*Base branch has advanced past feature \`${featureId}\`*`,
390	      driftReason,
391	      handoffPrUrl ? `PR: ${handoffPrUrl}` : null,
392	    ].filter(Boolean).join("\n");
393	
394	    try {
395	      const resp = await fetch(slackWebhookUrl, {
396	        method: "POST",
397	        headers: { "Content-Type": "application/json" },
398	        body: JSON.stringify({
399	          text: `[Drift Detected] Feature \`${featureId}\` requires human review`,
400	          blocks: [
401	            {
402	              type: "section",
403	              text: {
404	                type: "mrkdwn",
405	                text: slackBody,
406	              },
407	            },
408	          ],
409	        }),
410	      });
411	      if (!resp.ok) {
412	        emit({
413	          type: "drift_slack_failed",
414	          feature_id: featureId,
415	          status: resp.status,
416	        });
417	      } else {
418	        emit({ type: "drift_slack_sent", feature_id: featureId });
419	      }
420	    } catch (e) {
421	      emit({ type: "drift_slack_failed", feature_id: featureId, details: String(e) });
422	    }
423	  } else {
424	    emit({ type: "drift_slack_skipped", feature_id: featureId, reason: "no_webhook_url" });
425	  }
426	}
427	
428	// ── Main export ───────────────────────────────────────────────────────────────
429	
430	/**
431	 * Run one iteration of the feature reviewer for all in_handoff features in
432	 * a single workspace. Intended to be called from the orchestrator poll loop
433	 * every FEATURE_REVIEW_INTERVAL cycles.
434	 */
435	export async function runFeatureReviewCycle(opts: RunFeatureReviewCycleOpts): Promise<void> {
436	  const {
437	    workspaceRoot,
438	    baseBranch,
439	    mgmtRepoOwner,
440	    mgmtRepoName,
441	    githubToken,
442	    anthropicApiKey,
443	    slackWebhookUrl,
444	    emit,
445	  } = opts;
446	
447	  const CONFIDENCE_THRESHOLD = opts.semanticConfidenceThreshold ?? 0.80;
448	
449	  if (!githubToken) {
450	    emit({ type: "feature_review_skipped", reason: "no_github_token" });
451	    return;
452	  }
453	
454	  const featureIds = listFeatureIds(workspaceRoot);
455	
456	  for (const featureId of featureIds) {
457	    const statusYaml = readStatusYaml(workspaceRoot, featureId);
458	
459	    if (statusYaml.feature_status !== "in_handoff") continue;
460	
461	    if (statusYaml.drift_detected) {
462	      emit({
463	        type: "feature_review_skipped",
464	        feature_id: featureId,
465	        reason: "drift_already_detected",
466	      });
467	      continue;
468	    }
469	
470	    const featureBranchBaseSha = statusYaml.feature_branch_base_sha;
471	    if (!featureBranchBaseSha) {
472	      emit({
473	        type: "feature_review_skipped",
474	        feature_id: featureId,
475	        reason: "no_feature_branch_base_sha",
476	      });
477	      continue;
478	    }
479	
480	    // ── Step 1: Compare feature_branch_base_sha..baseBranch ──────────────────
481	    let compareResult: GitHubCompareResult;
482	    try {
483	      compareResult = curlJson([
484	        "-s",
485	        "-H", `Authorization: token ${githubToken}`,
486	        "-H", "Accept: application/vnd.github+json",
487	        `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/compare/${featureBranchBaseSha}...${baseBranch}`,
488	      ]) as GitHubCompareResult;
489	    } catch (e) {
490	      emit({
491	        type: "feature_review_compare_failed",
492	        feature_id: featureId,
493	        details: String(e),
494	      });
495	      continue;
496	    }
497	
498	    if (compareResult.ahead_by === 0) {
499	      emit({ type: "feature_review_no_drift", feature_id: featureId });
500	      continue;
501	    }
502	
503	    emit({
504	      type: "feature_review_new_commits",
505	      feature_id: featureId,
506	      new_commits: compareResult.ahead_by,
507	    });
508	
509	    // ── Step 2: Extract files changed in new base commits ─────────────────────
510	    const newBaseFiles = (compareResult.files ?? []).map((f) => f.filename);
511	
512	    // ── Step 3: Get files changed by this feature's management repo PR ────────
513	    const featureFiles: string[] = [];
514	    const handoffPrUrl = statusYaml.handoff_pr_url;
515	    if (handoffPrUrl) {
516	      const prMatch = /\/pull\/(\d+)$/.exec(handoffPrUrl);
517	      if (prMatch) {
518	        const prNumber = prMatch[1];
519	        try {
520	          const files = curlJson([
521	            "-s",
522	            "-H", `Authorization: token ${githubToken}`,
523	            "-H", "Accept: application/vnd.github+json",
524	            `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}/files`,
525	          ]) as Array<{ filename: string }>;
526	          if (Array.isArray(files)) {
527	            featureFiles.push(...files.map((f) => f.filename));
528	          }
529	        } catch (e) {
530	          emit({
531	            type: "feature_review_pr_files_failed",
532	            feature_id: featureId,
533	            details: String(e),
534	          });
535	        }
536	      }
537	    }
538	
539	    // ── Step 4: File-overlap classification ───────────────────────────────────
540	    const { hasOverlap, overlappingFiles } = classifyFileOverlap(newBaseFiles, featureFiles);
541	
542	    if (!hasOverlap) {
543	      // Task-level: auto-rebase
544	      emit({
545	        type: "feature_review_task_level_drift",
546	        feature_id: featureId,
547	        new_commits: compareResult.ahead_by,
548	      });
549	      const rebaseResult = tryAutoRebase(opts, featureId);
550	      if (rebaseResult.success) {
551	        emit({ type: "feature_review_rebased", feature_id: featureId });
552	      } else {
553	        emit({
554	          type: "feature_review_rebase_conflict",
555	          feature_id: featureId,
556	          details: rebaseResult.conflictDetails,
557	        });
558	        const driftReason = [
559	          `Rebase conflict: ${compareResult.ahead_by} new commits on ${baseBranch}.`,
560	          rebaseResult.conflictDetails?.slice(0, 200),
561	        ]
562	          .filter(Boolean)
563	          .join(" ");
564	        await escalateFeatureDrift(opts, featureId, driftReason);
565	      }
566	      continue;
567	    }
568	
569	    // File overlap — attempt semantic analysis
570	    emit({
571	      type: "feature_review_file_overlap",
572	      feature_id: featureId,
573	      overlapping_files: overlappingFiles,
574	    });
575	
576	    if (anthropicApiKey) {
577	      try {
578	        const newBaseSummary = (compareResult.files ?? [])
579	          .map((f) => {
580	            const patch = f.patch?.slice(0, 200) ?? "";
581	            return `${f.filename} (${f.status})${patch ? `\n${patch}` : ""}`;
582	          })
583	          .join("\n");
584	        const featureSummary = featureFiles.join("\n");
585	
586	        let technicalDesignSummary: string | undefined;
587	        const tdPath = join(workspaceRoot, "docs", "features", featureId, "technical-design.md");
588	        if (existsSync(tdPath)) {
589	          try {
590	            technicalDesignSummary = readFileSync(tdPath, "utf-8").slice(0, 3000);
591	          } catch { /* non-fatal — proceed without it */ }
592	        }
593	
594	        const analysis = await runSemanticAnalysis(
595	          overlappingFiles,
596	          newBaseSummary,
597	          featureSummary,
598	          anthropicApiKey,
599	          technicalDesignSummary,
600	        );
601	
602	        emit({
603	          type: "feature_review_semantic_analysis",
604	          feature_id: featureId,
605	          confidence: analysis.confidence,
606	          has_conflict: analysis.hasConflict,
607	          reasoning: analysis.reasoning,
608	        });
609	
610	        if (analysis.confidence >= CONFIDENCE_THRESHOLD && !analysis.hasConflict) {
611	          // High confidence no conflict → treat as task-level
612	          emit({
613	            type: "feature_review_task_level_drift",
614	            feature_id: featureId,
615	            new_commits: compareResult.ahead_by,
616	            reason: "semantic_override",
617	          });
618	          const rebaseResult = tryAutoRebase(opts, featureId);
619	          if (rebaseResult.success) {
620	            emit({ type: "feature_review_rebased", feature_id: featureId });
621	          } else {
622	            const driftReason = `Semantic analysis passed (confidence=${analysis.confidence.toFixed(2)}) but rebase failed: ${rebaseResult.conflictDetails?.slice(0, 200) ?? "unknown"}`;
623	            await escalateFeatureDrift(opts, featureId, driftReason);
624	          }
625	        } else {
626	          const driftReason = `Semantic conflict (confidence=${analysis.confidence.toFixed(2)}): ${analysis.reasoning}. Overlapping files: ${overlappingFiles.slice(0, 3).join(", ")}`;
627	          await escalateFeatureDrift(opts, featureId, driftReason);
628	        }
629	      } catch (e) {
630	        emit({
631	          type: "feature_review_semantic_failed",
632	          feature_id: featureId,
633	          details: String(e),
634	        });
635	        // Semantic analysis failed — escalate conservatively
636	        const driftReason = `File overlap on ${overlappingFiles.slice(0, 3).join(", ")} with ${compareResult.ahead_by} new base commits (semantic analysis unavailable)`;
637	        await escalateFeatureDrift(opts, featureId, driftReason);
638	      }
639	    } else {
640	      // No Anthropic key — escalate directly
641	      const driftReason = `File overlap on ${overlappingFiles.slice(0, 3).join(", ")} with ${compareResult.ahead_by} new base commits`;
642	      await escalateFeatureDrift(opts, featureId, driftReason);
643	    }
644	  }
645	}
