/**
 * Tests for poll/feature-review-cycle.ts (T4 — Feature Reviewer Daemon)
 *
 * Covers:
 *   1. classifyFileOverlap — no overlap returns hasOverlap: false
 *   2. classifyFileOverlap — overlap returns hasOverlap: true with correct files
 *   3. No new commits (ahead_by === 0) → emits feature_review_no_drift; skips
 *   4. New commits, no file overlap → calls tryAutoRebase (task-level path)
 *   5. Auto-rebase clean → emits feature_review_rebased; pushes
 *   6. Auto-rebase conflict → escalates; emits drift_escalated
 *   7. File overlap, no Anthropic key → escalates directly
 *   8. File overlap, semantic analysis: confidence ≥ threshold → auto-rebase
 *   9. File overlap, semantic analysis: confidence < threshold → escalate
 *  10. Slack set → drift_slack_sent emitted
 *  11. Slack absent → drift_slack_skipped emitted
 *  12. feature_status not in_handoff → skipped entirely
 *  13. drift_detected already true → skipped
 *  14. No feature_branch_base_sha → skipped
 *  15. No githubToken → emits feature_review_skipped
 *  16. GitHub compare API error → non-fatal; emits feature_review_compare_failed
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";

// ── Mocks ─────────────────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

vi.mock("../src/utils/curl-json.js", () => ({
  curlJson: vi.fn(),
}));

// Mock fetch for Slack webhook and Anthropic API calls
const fetchMock = vi.fn();
vi.stubGlobal("fetch", fetchMock);

import { execSync, spawnSync } from "node:child_process";
import { curlJson } from "../src/utils/curl-json.js";
import {
  classifyFileOverlap,
  runFeatureReviewCycle,
  tryAutoRebase,
  type RunFeatureReviewCycleOpts,
} from "../src/poll/feature-review-cycle.js";

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-drift-feature";
const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
const BASE_BRANCH = "main";
const GITHUB_TOKEN = "ghp_test_token";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Agent Test";
const MGMT_OWNER = "test-owner";
const MGMT_REPO = "test-mgmt-repo";
const BASE_SHA = "abc1234";
const HANDOFF_PR_URL = `https://github.com/${MGMT_OWNER}/${MGMT_REPO}/pull/99`;
const ANTHROPIC_API_KEY = "sk-ant-test";
const SLACK_WEBHOOK_URL = "https://hooks.slack.com/test";

const tmpDirs: string[] = [];

function makeWorkspace(featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "feature-review-cycle-"));
  tmpDirs.push(dir);
  const featureDir = join(dir, "docs", "features", featureId);
  mkdirSync(featureDir, { recursive: true });
  return dir;
}

function writeStatusYaml(
  wsRoot: string,
  status: Record<string, unknown>,
  featureId = FEATURE_ID,
): void {
  const featureDir = join(wsRoot, "docs", "features", featureId);
  mkdirSync(featureDir, { recursive: true });
  writeFileSync(join(featureDir, "status.yaml"), yamlStringify(status), "utf-8");
}

function readStatusYaml(
  wsRoot: string,
  featureId = FEATURE_ID,
): Record<string, unknown> {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", featureId, "status.yaml"),
      "utf-8",
    ),
  ) as Record<string, unknown>;
}

function makeInHandoffStatus(
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    feature_id: FEATURE_ID,
    feature_status: "in_handoff",
    feature_branch: FEATURE_BRANCH,
    feature_branch_base_sha: BASE_SHA,
    handoff_pr_url: HANDOFF_PR_URL,
    drift_detected: false,
    drift_reason: null,
    ...overrides,
  };
}

function makeOpts(
  wsRoot: string,
  overrides: Partial<RunFeatureReviewCycleOpts> = {},
): RunFeatureReviewCycleOpts {
  return {
    workspaceRoot: wsRoot,
    baseBranch: BASE_BRANCH,
    mgmtRepoOwner: MGMT_OWNER,
    mgmtRepoName: MGMT_REPO,
    githubToken: GITHUB_TOKEN,
    gitAuthorEmail: GIT_AUTHOR_EMAIL,
    gitAuthorName: GIT_AUTHOR_NAME,
    emit: vi.fn(),
    ...overrides,
  };
}

function mockGitSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr: "",
    status: 0,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockGitPushFailure(
  stderr = "fatal: remote rejected",
): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: "",
    stderr,
    status: 1,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockCompareResult(aheadBy: number, files: string[] = []): unknown {
  return {
    ahead_by: aheadBy,
    files: files.map((f) => ({ filename: f, status: "modified" })),
  };
}

function mockPrFiles(filenames: string[]): unknown {
  return filenames.map((f) => ({ filename: f }));
}

function mockAnthropicSuccess(
  confidence: number,
  hasConflict: boolean,
  reasoning = "no conflict detected",
): Response {
  const body = JSON.stringify({
    content: [
      {
        type: "text",
        text: JSON.stringify({
          confidence,
          has_conflict: hasConflict,
          reasoning,
        }),
      },
    ],
  });
  return {
    ok: true,
    status: 200,
    json: () => Promise.resolve(JSON.parse(body)),
    text: () => Promise.resolve(body),
  } as unknown as Response;
}

function mockSlackSuccess(): Response {
  return {
    ok: true,
    status: 200,
    text: () => Promise.resolve("ok"),
  } as unknown as Response;
}

afterEach(() => {
  vi.resetAllMocks();
  fetchMock.mockReset();
  for (const dir of tmpDirs.splice(0)) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
  }
});

// ── classifyFileOverlap unit tests ────────────────────────────────────────────

describe("classifyFileOverlap", () => {
  it("returns hasOverlap: false when there is no intersection", () => {
    const result = classifyFileOverlap(
      ["src/foo.ts", "README.md"],
      ["docs/bar.md", "src/baz.ts"],
    );
    expect(result.hasOverlap).toBe(false);
    expect(result.overlappingFiles).toHaveLength(0);
  });

  it("returns hasOverlap: true with the intersecting files", () => {
    const result = classifyFileOverlap(
      ["src/foo.ts", "README.md", "src/shared.ts"],
      ["src/shared.ts", "docs/bar.md"],
    );
    expect(result.hasOverlap).toBe(true);
    expect(result.overlappingFiles).toEqual(["src/shared.ts"]);
  });

  it("handles empty arrays", () => {
    expect(classifyFileOverlap([], []).hasOverlap).toBe(false);
    expect(classifyFileOverlap(["src/foo.ts"], []).hasOverlap).toBe(false);
    expect(classifyFileOverlap([], ["src/foo.ts"]).hasOverlap).toBe(false);
  });

  it("returns all overlapping files when multiple intersect", () => {
    const result = classifyFileOverlap(
      ["a.ts", "b.ts", "c.ts"],
      ["b.ts", "c.ts", "d.ts"],
    );
    expect(result.hasOverlap).toBe(true);
    expect(result.overlappingFiles).toEqual(expect.arrayContaining(["b.ts", "c.ts"]));
    expect(result.overlappingFiles).toHaveLength(2);
  });
});

// ── No new commits ─────────────────────────────────────────────────────────────

describe("runFeatureReviewCycle — no new commits", () => {
  it("emits feature_review_no_drift and does not rebase when ahead_by is 0", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    // compare returns ahead_by: 0
    vi.mocked(curlJson).mockReturnValueOnce(mockCompareResult(0));

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "feature_review_no_drift" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });
});

// ── No overlap → auto-rebase (task-level) ─────────────────────────────────────

describe("runFeatureReviewCycle — no file overlap, clean rebase", () => {
  it("emits feature_review_rebased and pushes after clean rebase", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    // compare: 2 new commits, files that don't overlap with feature PR
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(2, ["other-feature/task.yaml"]))
      .mockReturnValueOnce(mockPrFiles(["docs/features/our-feature/tasks/T1.yaml"]));

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "feature_review_task_level_drift")).toBe(true);
    expect(events.some((e) => e.type === "feature_review_rebased" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "drift_escalated")).toBe(false);
  });
});

// ── No overlap → rebase conflict → escalate ───────────────────────────────────

describe("runFeatureReviewCycle — no file overlap, rebase conflict", () => {
  it("escalates when rebase fails and emits drift_escalated", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(3, ["other-feature/task.yaml"]))
      .mockReturnValueOnce(mockPrFiles(["docs/features/our-feature/tasks/T1.yaml"]));

    // git rebase fails
    vi.mocked(execSync)
      .mockReturnValueOnce(undefined as unknown as Buffer) // git fetch
      .mockReturnValueOnce(undefined as unknown as Buffer) // git checkout -B
      .mockImplementationOnce(() => {
        const err = new Error("CONFLICT") as NodeJS.ErrnoException & { stderr?: string };
        err.stderr = "CONFLICT (content): Merge conflict in foo.ts";
        throw err;
      }) // git rebase
      .mockReturnValue(undefined as unknown as Buffer); // git rebase --abort + escalation git commands

    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
    fetchMock.mockResolvedValue(mockSlackSuccess());

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, {
        emit: (e) => events.push(e),
        slackWebhookUrl: SLACK_WEBHOOK_URL,
      }),
    );

    expect(events.some((e) => e.type === "feature_review_rebase_conflict")).toBe(true);
    expect(events.some((e) => e.type === "drift_escalated" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "drift_slack_sent")).toBe(true);

    // status.yaml should have drift_detected: true
    const status = readStatusYaml(wsRoot);
    expect(status.drift_detected).toBe(true);
    expect(typeof status.drift_reason).toBe("string");
  });
});

// ── File overlap, no Anthropic key → escalate ────────────────────────────────

describe("runFeatureReviewCycle — file overlap, no Anthropic key", () => {
  it("escalates directly without semantic analysis when no API key", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    const sharedFile = "src/shared.ts";
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(1, [sharedFile]))
      .mockReturnValueOnce(mockPrFiles([sharedFile]));

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
    fetchMock.mockResolvedValue(mockSlackSuccess());

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, {
        emit: (e) => events.push(e),
        slackWebhookUrl: SLACK_WEBHOOK_URL,
        // anthropicApiKey not set
      }),
    );

    expect(events.some((e) => e.type === "feature_review_file_overlap")).toBe(true);
    expect(events.some((e) => e.type === "drift_escalated" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "feature_review_semantic_analysis")).toBe(false);
  });
});

// ── File overlap, semantic analysis above threshold → auto-rebase ─────────────

describe("runFeatureReviewCycle — file overlap, semantic confidence high", () => {
  it("auto-rebases when semantic analysis returns high confidence no-conflict", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    const sharedFile = "src/shared.ts";
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(1, [sharedFile]))
      .mockReturnValueOnce(mockPrFiles([sharedFile]));

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    // Anthropic API returns high confidence, no conflict
    fetchMock.mockResolvedValue(mockAnthropicSuccess(0.95, false, "changes are in separate functions"));

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, {
        emit: (e) => events.push(e),
        anthropicApiKey: ANTHROPIC_API_KEY,
      }),
    );

    expect(events.some((e) => e.type === "feature_review_semantic_analysis" && e.confidence === 0.95)).toBe(true);
    expect(events.some((e) => e.type === "feature_review_task_level_drift")).toBe(true);
    expect(events.some((e) => e.type === "feature_review_rebased")).toBe(true);
    expect(events.some((e) => e.type === "drift_escalated")).toBe(false);
  });
});

// ── File overlap, semantic analysis below threshold → escalate ────────────────

describe("runFeatureReviewCycle — file overlap, semantic confidence low", () => {
  it("escalates when semantic analysis returns low confidence or has_conflict: true", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    const sharedFile = "src/main.ts";
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(2, [sharedFile]))
      .mockReturnValueOnce(mockPrFiles([sharedFile]));

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    // Anthropic API returns conflict detected
    fetchMock
      .mockResolvedValueOnce(mockAnthropicSuccess(0.30, true, "same function signature changed"))
      .mockResolvedValueOnce(mockSlackSuccess()); // Slack

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, {
        emit: (e) => events.push(e),
        anthropicApiKey: ANTHROPIC_API_KEY,
        slackWebhookUrl: SLACK_WEBHOOK_URL,
      }),
    );

    expect(events.some((e) => e.type === "feature_review_semantic_analysis" && e.has_conflict === true)).toBe(true);
    expect(events.some((e) => e.type === "drift_escalated" && e.feature_id === FEATURE_ID)).toBe(true);
    expect(events.some((e) => e.type === "drift_slack_sent")).toBe(true);

    const status = readStatusYaml(wsRoot);
    expect(status.drift_detected).toBe(true);
  });
});

// ── Slack absent → skip gracefully ────────────────────────────────────────────

describe("runFeatureReviewCycle — Slack absent", () => {
  it("emits drift_slack_skipped and does not throw when SLACK_WEBHOOK_URL is absent", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    const sharedFile = "src/shared.ts";
    vi.mocked(curlJson)
      .mockReturnValueOnce(mockCompareResult(1, [sharedFile]))
      .mockReturnValueOnce(mockPrFiles([sharedFile]));

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, {
        emit: (e) => events.push(e),
        // slackWebhookUrl not set
      }),
    );

    expect(events.some((e) => e.type === "drift_slack_skipped" && e.reason === "no_webhook_url")).toBe(true);
    expect(fetchMock).not.toHaveBeenCalled();
  });
});

// ── Feature not in_handoff → skip ─────────────────────────────────────────────

describe("runFeatureReviewCycle — feature not in_handoff", () => {
  it("skips features that are not in_handoff", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, {
      feature_id: FEATURE_ID,
      feature_status: "in_implementation",
    });

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(vi.mocked(curlJson)).not.toHaveBeenCalled();
    expect(events.length).toBe(0);
  });
});

// ── drift_detected already set → skip ────────────────────────────────────────

describe("runFeatureReviewCycle — drift already detected", () => {
  it("emits feature_review_skipped and makes no API calls when drift_detected is true", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus({ drift_detected: true, drift_reason: "prior reason" }));

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "feature_review_skipped" && e.reason === "drift_already_detected")).toBe(true);
    expect(vi.mocked(curlJson)).not.toHaveBeenCalled();
  });
});

// ── No feature_branch_base_sha → skip ────────────────────────────────────────

describe("runFeatureReviewCycle — no feature_branch_base_sha", () => {
  it("emits feature_review_skipped when base SHA is absent", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, {
      feature_id: FEATURE_ID,
      feature_status: "in_handoff",
      feature_branch: FEATURE_BRANCH,
      // feature_branch_base_sha not set
