    expect(vi.mocked(curlJson)).not.toHaveBeenCalled();
  });
});

// ── No githubToken → skip ─────────────────────────────────────────────────────

describe("runFeatureReviewCycle — no githubToken", () => {
  it("emits feature_review_skipped and makes no API calls", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    const events: Record<string, unknown>[] = [];
    await runFeatureReviewCycle(
      makeOpts(wsRoot, { githubToken: "", emit: (e) => events.push(e) }),
    );

    expect(
      events.some((e) => e.type === "feature_review_skipped" && e.reason === "no_github_token"),
    ).toBe(true);
    expect(vi.mocked(curlJson)).not.toHaveBeenCalled();
  });
});

// ── GitHub compare API error → non-fatal ─────────────────────────────────────

describe("runFeatureReviewCycle — compare API error", () => {
  it("emits feature_review_compare_failed and continues (non-fatal)", async () => {
    const wsRoot = makeWorkspace();
    writeStatusYaml(wsRoot, makeInHandoffStatus());

    vi.mocked(curlJson).mockImplementationOnce(() => {
      throw new Error("API rate limited");
    });

    const events: Record<string, unknown>[] = [];
    await expect(
      runFeatureReviewCycle(makeOpts(wsRoot, { emit: (e) => events.push(e) })),
    ).resolves.not.toThrow();

    expect(
      events.some(
        (e) => e.type === "feature_review_compare_failed" && e.feature_id === FEATURE_ID,
      ),
    ).toBe(true);
  });
});

